///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name ins_search
 * @description 일반 상품(금) 조회한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ins_search = async function() {
    /**
     * SrM-000243255
     */
    if (!await scwin.checkSearchCondition()) {
        return false;
    }

    // 검색일 체크
    if ($c.stf.compareFromToDate2(edt_SDATE, edt_EDATE) === false) {
        return false;
    }

    // 조회 버튼 클릭 후 바로 버튼 클릭 안되게 처리 20220922
    fn_SetDisableSelectBtn(btn_search, true);
    const sbmOptions = {
        id : "sbm_dts_List",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name checkSearchCondition
 * @description SrM-000243255  조회조건을 체크 (표준코드, 한글종목명, 발행기관코드에 값이 입력 안되었을 경우 / 날짜 조건은 필수로 입력되도록.. 날짜 입력가능 범위는 5년..)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkSearchCondition = async function() {
    const sStdCd = txb_pISU_CD.getValue();
    const sIsuKorNm = txb_pISU_KOR_NM.getValue();
    const sSDateFrom = edt_SDATE.getValue(); // 코드부여일(from)
    const sSDateTo = edt_EDATE.getValue(); // 코드부여일(to)

    if (sStdCd === "" && sIsuKorNm === "") {
        if (sSDateFrom === "" && sSDateTo === "") {
            const msg = "조회조건을 최소 1개 이상 입력하세요.\n\n" + "[표준코드, 한글종목명] 중 1개 이상의 조건을 입력하거나, \n" + "[영업일]의 검색기간을 1년 이내로 입력하세요.";
            await $c.win.alert(msg);
            return false;
        }

        // 코드부여일 체크
        if (sSDateFrom !== "" && sSDateTo !== "") {
            if (Number($c.ut.cGetPlusYear(sSDateFrom, 1)) < Number(sSDateTo)) {
                await $c.win.alert("영업일의 검색기간은 1년 이내로 입력하세요.");
                edt_SDATE.focus();
                return false;
            }
        } else if (sSDateFrom !== "" || sSDateTo !== "") {
            await $c.win.alert("영업일의 검색기간은 1년 이내로 입력하세요.");
            if (sSDateFrom === "") {
                edt_SDATE.focus();
            } else {
                edt_EDATE.focus();
            }
            return false;
        }
    }
    return true;
};
